function checkout() {
    const canvas = document.createElement('canvas');
    document.body.appendChild(canvas);
    const ctx = canvas.getContext('2d');
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;

    let pulseSize = 100, growing = true, particles = [];

    function createParticle() {
        particles.push({ x: canvas.width / 2, y: canvas.height / 2, size: Math.random() * 5 + 2, alpha: 1 });
    }

    function animateParticles() {
        for (let i = particles.length - 1; i >= 0; i--) {
            const p = particles[i];
            p.alpha -= 0.02;
            if (p.alpha <= 0) particles.splice(i, 1);
        }
    }

    function drawParticles() {
        ctx.fillStyle = 'rgba(255, 223, 0, 1)';
        particles.forEach(p => {
            ctx.globalAlpha = p.alpha;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        });
        ctx.globalAlpha = 1;
    }

    function drawButton() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = 'gold';
        ctx.beginPath();
        ctx.arc(canvas.width / 2, canvas.height / 2, pulseSize, 0, Math.PI * 2);
        ctx.fill();
    }

    function update() {
        pulseSize += growing ? 1 : -1;
        if (pulseSize > 120 || pulseSize < 100) growing = !growing;
        createParticle();
        animateParticles();
    }

    function loop() {
        update();
        drawButton();
        drawParticles();
        requestAnimationFrame(loop);
    }

    setTimeout(() => {
        window.parent.postMessage("INSTALL_CLICK", "*");
    }, 100);

    loop();
}
